fragment.source:
mat2 turn(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}
float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float noise21(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash21(i),hash21(i+vec2(1.,0.)),f.x),mix(hash21(i+vec2(0.,1.)),hash21(i+1.),f.x),f.y);}
const mat2 FBM_TURN=mat2(.90044710,-.43496553,.43496553,.90044710);
float fbm(vec2 p,int octaves){float n=0.,a=.5;for(int i=0;i<4;i++){if(i>=octaves)break;n+=a*noise21(p);p=FBM_TURN*p*2.01+vec2(3.4,1.7);a*=.5;}return n;}
vec2 eddy(vec2 p,vec2 c,float a,float r){vec2 d=p-c;return c+turn(a*exp(-dot(d,d)/(r*r)))*d;}
float inkFlowClock(){return vrchPhase_speed()*.32+vrchPhase_accent()*.85+vrchPhase_motion()*uParam_pull*1.4;}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 scale=iResolution.xy/min(iResolution.x,iResolution.y);
 vec2 p=(2.*fragCoord-iResolution.xy)/min(iResolution.x,iResolution.y);
 // Both clocks only advance. Musical accents carry material forwards;
 // there is no amplitude-driven expansion/retraction of the silhouette.

 vec2 hand=(clamp(vec2(uParam_touch_x,uParam_touch_y)/max(uParam_contact,1e-8),0.,1.)*2.-1.)*scale;
 vec2 wake=(clamp(vec2(uParam_wake_x,uParam_wake_y)/max(uParam_wake,1e-8),0.,1.)*2.-1.)*scale;
 vec2 stroke=hand-wake;
 stroke*=min(1.,.8/max(length(stroke),1e-6));
 float contact=smoothstep(.03,.75,min(uParam_contact,uParam_wake));
 float motion=smoothstep(.008,.18,uParam_motion);
 float force=uParam_pull*contact*motion;
 vec2 tail=hand-stroke;
 float along=clamp(dot(p-tail,stroke)/max(dot(stroke,stroke),1e-6),0.,1.);
 vec2 d=p-mix(tail,hand,along);
 float sweep=exp(-dot(d,d)/.24);
 // A sweep carries a broad, tapering sheet of ink; the lagged location leaves
 // a decaying wake rather than a tiny distortion tied to the fingertip.
 vec2 carried=p-stroke*force*sweep*1.4;
 float density=0.;
 // Overlapping parcels enter, roll forward and disperse. Each parcel has a
 // finite advection age, so curls never wind into an ever-finer fixed spiral.
 // Crossfades are pigment turnover, not reversing geometry.
 for(int i=0;i<3;i++){
  // Each parcel's age, seed, placement and turn do not depend on the pixel: the frame stage computes them.
  vec4 placed=vrchFrameData(2*i),turned=vrchFrameData(2*i+1);
  float age=turned.z,seed=placed.w,life=placed.z;
  vec2 parcel=(carried-placed.xy)*1.22;
  vec2 q=mat2(turned.x,-turned.y,turned.y,turned.x)*parcel;
  q=eddy(q,vec2(-.10,.16),(.5+age*2.8)*(.6+uParam_curve),.95);
  q=eddy(q,vec2(.32,-.32),-.7-age*.8,.7);
  float river=q.x+(fbm(q*1.2+seed,2)-.5)*.20;
  float width=(.095+.065*noise21(vec2(q.y*1.5+seed,2.)))*(.70+uParam_fold*.8);
  float ty=q.y/1.12,ty2=ty*ty;
  float taper=exp(-ty2*ty2);
  float wx=(river-.03)/(width*2.4);
  float wash=exp(-wx*wx)*taper;
  // Cloud shifts the edge by at most .06; body <= 4.36*mainInk and the fringe term <= .88*wash.
  float reach=exp(-pow(max(abs(river)-.06,0.)/width,3.2))*taper*4.36+wash*.88;
  if(reach*life<1e-4)continue;
  vec2 fibers=vec2(river*8.,q.y*2.4-age*1.1+seed*2.);
  float cloud=fbm(fibers,2);
  float edge=river+(cloud-.5)*.12;
  float mainInk=exp(-pow(abs(edge)/width,3.2))*taper;
  float front=noise21(vec2(q.y*2.5-age*1.6+seed*3.,1.));
  float body=mainInk*(.16+4.2*smoothstep(.30,.70,front)*(.6+.4*cloud));
  float fringe=wash*(1.-mainInk*.98);
  density+=(body+fringe*.045)*life;
  // Threads only show where the ink is not yet saturated: skip them where they cannot change the colour.
  float threadMax=fringe*life*(.18+.65*uParam_relief);
  if(threadMax*exp(-1.8*density)>.002){
   float grain=noise21(fibers*2.3+vec2(5.7,-age))*.5;
   float tangled=fbm(vec2(river*(22.+uParam_bands*3.),q.y*3.-age)+vec2(cloud*2.5,grain),2);
   float th=clamp(1.-abs(tangled-.48)*9.,0.,1.);
   density+=threadMax*th*th*th;
  }

 }
 float paper=noise21(fragCoord*.72);
 vec3 paperColor=vec3(.87,.855,.815)+(paper-.5)*.007;
 vec3 ink=max(uParam_ink.rgb*.18,vec3(.001));
 fragColor=vec4(mix(paperColor,ink,1.-exp(-density*1.8)),1.);
}

frame.source:
// Texels 2i and 2i+1 hold parcel i: offset (centre plus drift), life and seed;
// then the parcel's turn as cos and sin, and its age.
void vrchFrame(in int texel,out vec4 value){
 int i=texel/2;
 float clock=inkFlowClock()*.22+float(i)/3.;
 float cycle=floor(clock);
 float age=fract(clock);
 float seed=cycle*3.-float(i);
 if(texel==2*i){
  float life=sin(age*3.14159265);life*=life;
  vec2 center=vec2((hash21(vec2(seed,2.))-.5)*.7,(hash21(vec2(seed,7.))-.5)*.65);
  vec2 drift=turn((hash21(vec2(seed,9.))-.5)*1.6)*vec2(.25,.8);
  value=vec4(center+drift*(age-.5),life,seed);
 }else{
  float a=-.45+(hash21(vec2(seed,5.))-.5)*2.4;
  value=vec4(cos(a),sin(a),age,0.0);
 }
}
